mapper.select:
SELECT g.id, s.name AS stationName, g.open_reason AS openReason, u.nickname AS applyUserName, g.apply_time AS applyTime, g.status, au.nickname AS auditUserName, g.audit_time AS auditTime, g.execute_time AS executeTime, g.reject_reason AS rejectReason, g.remark, g.reserve1, g.reserve2, g.creator, g.updater, g.create_time AS createTime, g.update_time AS updateTime FROM gate_open g LEFT JOIN station_info s ON g.station_id = s.id AND s.deleted = 0 LEFT JOIN user_info u ON g.apply_user_id = u.id AND u.deleted = 0 LEFT JOIN user_info au ON g.audit_user_id = au.id AND au.deleted = 0 WHERE g.deleted = 0
AND g.station_id = #{reqVO.stationId}
AND g.open_reason = #{reqVO.openReason}
AND g.apply_user_id = #{reqVO.applyUserId}
AND g.apply_time BETWEEN FROM_UNIXTIME(#{reqVO.applyTime[0]}) AND FROM_UNIXTIME(#{reqVO.applyTime[1]})
AND g.status = #{reqVO.status}
AND g.audit_user_id = #{reqVO.auditUserId}
AND g.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
ORDER BY g.id DESC
